Item.method_code:
var itemId = System.Security.SecurityElement.Escape(CCO.DB.InnDatabase.QuoteValue(getID()));

Aras.Server.Core.GuidModule.IsIdValid(itemId, true);

var query = getInnovator().newItem("ItemPresentationConfiguration", "delete");
query.setAttribute("where", "item_id='" + itemId + "'");

Aras.Server.Security.Identity administratorsIdentity = Aras.Server.Security.Identity.GetByName("Administrators");
using (CCO.Permissions.GrantIdentity(administratorsIdentity))
{
	return query.apply();
}
